package com.example.budgetapp.health;
import java.time.*;
import org.junit.Test;
import static org.junit.Assert.*;
public class NotificationHealthControllerTest {
 @Test public void rebindThrottleUsesMonotonicTimeAndStateUpdatesNotify(){var elapsed=new java.util.concurrent.atomic.AtomicLong(100);var health=new NotificationHealthController(Clock.fixed(Instant.ofEpochMilli(5),ZoneOffset.UTC),null,elapsed::get);var changes=new java.util.concurrent.atomic.AtomicInteger();health.addListener(changes::incrementAndGet);health.onAuthorization(true);assertTrue(health.shouldRequestRebind());health.onDisconnected();assertFalse(health.shouldRequestRebind());elapsed.addAndGet(30000);assertTrue(health.shouldRequestRebind());health.onConnected();assertFalse(health.shouldRequestRebind());health.onAuthorization(false);assertTrue(changes.get()>=4);assertFalse(health.shouldRequestRebind());}
 @Test public void lastConnectionIsNotCurrentConnection(){Clock clock=Clock.fixed(Instant.ofEpochMilli(200),ZoneOffset.UTC);var health=new NotificationHealthController(clock,123L);assertEquals(NotificationHealth.Connection.UNKNOWN,health.snapshot().connection);health.onAuthorization(true);assertNotEquals(NotificationHealth.Connection.CONNECTED,health.snapshot().connection);health.onConnected();assertEquals(NotificationHealth.Connection.CONNECTED,health.snapshot().connection);assertEquals(Long.valueOf(200),health.snapshot().lastConnectedAtMs);health.onEvent();assertEquals(Long.valueOf(200),health.snapshot().lastEventAtMs);health.onAuthorization(false);assertEquals(NotificationHealth.Connection.DISCONNECTED,health.snapshot().connection);var restart=new NotificationHealthController(clock,health.snapshot().lastConnectedAtMs);assertNotEquals(NotificationHealth.Connection.CONNECTED,restart.snapshot().connection);}
}
